import React, { useState } from 'react';
import { InputText } from 'primereact/inputtext';
import { Calendar } from 'primereact/calendar';
import { InputNumber } from 'primereact/inputnumber';
import { Button } from 'primereact/button';

export default function OrderForm({ add }) {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState(null);
  const [date, setDate] = useState(null);

  const submit = (e) => {
    e.preventDefault();
    if (!description || !amount || !date) return;
    add({ id: Date.now(), description, amount, date: date.toISOString().split('T')[0] });
    setDescription(''); setAmount(null); setDate(null);
  };

  return (
    <form onSubmit={submit} className="p-3 border rounded mb-3 bg-white">
      <h5>Add Order</h5>
      <div className="mb-2">
        <InputText placeholder="Description" value={description} onChange={e => setDescription(e.target.value)} className="w-100" />
      </div>
      <div className="mb-2">
        <InputNumber value={amount} onValueChange={e => setAmount(e.value)} placeholder="Amount" mode="currency" currency="INR" locale="en-IN" className="w-100" />
      </div>
      <div className="mb-3">
        <Calendar value={date} onChange={e => setDate(e.value)} placeholder="Date" showIcon className="w-100" />
      </div>
      <Button label="Add Order" icon="pi pi-check" type="submit" className="p-button-primary w-100" />
    </form>
  );
}
