import React from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  LineElement,
  PointElement,
  LinearScale,
  CategoryScale,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';

ChartJS.register(
  LineElement,
  PointElement,
  LinearScale,
  CategoryScale,
  Title,
  Tooltip,
  Legend
);

const chartData = {
  labels: ['2025-06-25', '2025-06-26', '2025-06-27'],
  datasets: [
    { label: 'Orders', data: [100, 200, 150], borderColor: 'green', fill: false },
    { label: 'Expenses', data: [50, 70, 90], borderColor: 'red', fill: false },
  ],
};

export default function Summary() {
  return (
    <div className="chart-container">
      <Line data={chartData} />
    </div>
  );
}
