import React from 'react';
import { DataTable } from 'primereact/datatable';
import { Column } from 'primereact/column';
import { Tag } from 'primereact/tag';
export default function ExpenseList({ data }) {
  const total = data.reduce((sum, item) => sum + (item.amount || 0), 0);
 const amountTemplate = (rowData) => {
    return `₹${rowData.amount.toFixed(2)}`;
  };
  return (
    <div className="card p-3 mb-3">
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h5 className="mb-0">Expenses List</h5>
        <Tag severity="danger" value={`Total: ₹${total.toFixed(2)}`} />
      </div>

      <DataTable value={data} paginator rows={5} responsiveLayout="scroll">
        <Column field="date" header="Date" sortable></Column>
        <Column field="desc" header="Description" sortable></Column>
        <Column field="amount" header="Amount (₹)" body={amountTemplate} sortable></Column>
      </DataTable>
    </div>
  );
}
